// A harness that serves requests through the same mux the binary does.
//
// 196 handlers had no coverage at all, and every permission rule, error code and
// status this product returns lives in one of them. Checking those by starting a
// container and driving it by hand is what happened instead — which means it
// happened when somebody remembered to, and only for the path they were
// thinking about.
type testServer struct {
	t   *testing.T
	app *App
	// admin is the bootstrap administrator's session cookie.
	admin     *http.Cookie
	adminName string
	// logs holds everything the app wrote while the test ran. Some behaviour is
	// only visible here: work the product does on its own, and failures it
	// deliberately survives rather than reporting to the caller.
	logs *bytes.Buffer
}

// logged reports whether any line written so far contains every fragment.
func (s *testServer) logged(fragments ...string) bool {
	text := s.logs.String()
	for _, fragment := range fragments {
		if !strings.Contains(text, fragment) {
			return false
		}
	}
	return true
}

// harnessRun makes every account this file creates unique to one `go test`, so
// a suite that leaves a row behind still runs the next time. Cleanup below is
// best effort; this is what makes the tests not depend on it.
var harnessRun = time.Now().UnixNano() % 1e9

// harnessStamp is the second this `go test` started, carried in the name of
// every database the harness creates. v0.128 taught the harness to drop its
// template on the way out; a run that is interrupted never gets there, and
// interruption is ordinary — Ctrl-C, an editor's stop button, a timeout, or
// scripts/mutation-check.py killing a run it no longer needs. Forty-three
// databases and 409 MB accumulated in one working session that way.
//
// Cleanup that only happens on a clean exit does not happen. So the name says
// when it was made, and each run sweeps what earlier runs abandoned.
var harnessStamp = time.Now().Unix()

// harnessStale is how long a leftover has to sit before a later run removes it.
// Long enough that a slow suite running beside this one is never touched.
const harnessStale = 2 * time.Hour

var harnessAccounts atomic.Int64

// accountName turns a readable stem into a name no earlier run can collide with.
func accountName(stem string) string {
	return fmt.Sprintf("%s_%d_%d", stem, harnessRun, harnessAccounts.Add(1))
}

func newTestServer(t *testing.T) *testServer {
	t.Helper()
	dsn := os.Getenv("WEEKLY_TEST_POSTGRES_DSN")
	if dsn == "" {
		t.Skip("WEEKLY_TEST_POSTGRES_DSN is not configured")
	}
	// Each server gets its own database. Sharing one made the suite depend on
	// its own cleanup: the bootstrap administrator is only created when no
	// administrator exists, so a single leftover row turned every later run into
	// a wall of INVALID_CREDENTIALS.
	dsn = createScratchDatabase(t, dsn)

	// The four directories are derived from stateDirectory at package init, so
	// each has to be pointed somewhere writable on its own.
	//
	// It used to be three. customPPTXPath was the one left behind — which is
	// why no test had ever uploaded a PPTX template: the upload answered
	// STORAGE_ERROR because it was trying to write under /var/lib/weekly. The
	// whole organisation template feature, cascade included, was unreachable
	// from a test by an omission in this list.
	workspace := t.TempDir()
	state, attachments := stateDirectory, stateDirectoryAttachments
	imports, templates := importDirectory, customPPTXPath
	stateDirectory = workspace
	stateDirectoryAttachments = workspace + "/attachments"
	importDirectory = workspace + "/imports"
	customPPTXPath = workspace + "/templates/weekly-report.pptx"
	t.Cleanup(func() {
		stateDirectory, stateDirectoryAttachments = state, attachments
		importDirectory, customPPTXPath = imports, templates
	})

	t.Setenv("WEEKLY_POSTGRES_DSN", dsn)
	adminName := accountName("harnessadmin")
	t.Setenv("WEEKLY_BOOTSTRAP_ADMIN", adminName)
	t.Setenv("WEEKLY_BOOTSTRAP_ADMIN_PASSWORD", "HarnessAdmin1234")
	t.Setenv("WEEKLY_ALLOW_SECRET_RESET", "true")

	ctx, cancel := context.WithCancel(context.Background())
	logs := &bytes.Buffer{}
	app, err := New(ctx, Options{
		Logger: slog.New(slog.NewTextHandler(logs, nil)),
		Web:    fstest.MapFS{"index.html": &fstest.MapFile{Data: []byte("<!doctype html>")}},
		Build:  BuildInfo{Version: "test"},
	})
	if err != nil {
		cancel()
		t.Fatalf("build the app: %v", err)
	}
	t.Cleanup(func() { cancel(); app.Close() })

	server := &testServer{t: t, app: app, logs: logs}
	server.adminName = adminName
	server.admin = server.signIn(adminName, "HarnessAdmin1234")
	return server
}

// request issues one request through the mux. Origin is set to the request host
// so session calls pass the CSRF check; tests that need it absent say so.
func (s *testServer) request(method, path string, body any, cookie *http.Cookie) *httptest.ResponseRecorder {
	s.t.Helper()
	var payload io.Reader
	if body != nil {
		encoded, err := json.Marshal(body)
		if err != nil {
			s.t.Fatal(err)
		}
		payload = bytes.NewReader(encoded)
	}
	r := httptest.NewRequest(method, path, payload)
	if body != nil {
		r.Header.Set("Content-Type", "application/json")
	}
	r.Header.Set("Origin", "http://"+r.Host)
	if cookie != nil {
		r.AddCookie(cookie)
	}
	w := httptest.NewRecorder()
	// Handler(), not mux: the chain outside it sets the trace id, recovers a
	// panic, and writes the security headers. Calling the mux directly tested
	// the handlers and left everything the customer's request passes through on
	// the way there unexercised — which is how the trace id the screen shows a
	// reader came to appear in no log line at all.
	s.app.Handler().ServeHTTP(w, r)
	return w
}

// refusal is what a caller can read off a refused response: the code and the
// sentence. Not the trace id — that identifies this one request and is supposed
// to differ every time, so two refusals that read identically to a person still
// differ byte for byte.
func refusal(t *testing.T, recorder *httptest.ResponseRecorder) string {
	t.Helper()
	var body struct {
		Error struct {
			Code    string `json:"code"`
			Message string `json:"message"`
		} `json:"error"`
	}
	if err := json.Unmarshal(recorder.Body.Bytes(), &body); err != nil {
		t.Fatalf("decode a refusal: %v (%s)", err, recorder.Body.String())
	}
	return body.Error.Code + " " + body.Error.Message
}

