func TestAttachmentCleanupKeepsAnEmptyDirectoryForALiveReport(t *testing.T) {
	server := newTestServer(t)
	author := server.createUser("capture_empty", "USER", nil)
	reportID, _ := server.draft(author, "2026-08-24", "빈 첨부 디렉터리")
